enum Signal {
    Quit,
    Move { x: i32, y: i32 },
    Write(String),
}

fn describe(signal: Signal) -> String {
    match signal {
        Signal::Quit => String::from("quit"),
        Signal::Move { x, y } => format!("move to {x}, {y}"),
        Signal::Write(text) => format!("write: {text}"),
    }
}

fn classify(value: i32) -> &'static str {
    match value {
        number if number < 0 => "negative",
        0 => "zero",
        _ => "positive",
    }
}
